PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (id TEXT PRIMARY KEY, tg_id TEXT UNIQUE NOT NULL, username TEXT, is_premium INTEGER DEFAULT 0, points INTEGER DEFAULT 0, predictions_count INTEGER DEFAULT 0, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), tours_played INTEGER DEFAULT 0, ton_wallet TEXT, ton_consent INTEGER DEFAULT 0, ton_earned REAL DEFAULT 0, ton_distributed REAL DEFAULT 0, fav_team TEXT);
CREATE TABLE matches (id TEXT PRIMARY KEY, home_team TEXT NOT NULL, away_team TEXT NOT NULL, date TEXT, time TEXT, round TEXT, status TEXT DEFAULT 'upcoming', home_score INTEGER, away_score INTEGER, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), grp TEXT, venue TEXT, card_home TEXT, card_away TEXT, is_active INTEGER DEFAULT 1, week_id TEXT, result TEXT, match_date_utc TEXT, match_date_local TEXT);
CREATE TABLE predictions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, match_id TEXT NOT NULL, prediction_type TEXT NOT NULL, predicted_score TEXT, points_earned INTEGER, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE rewards (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, week INTEGER, points INTEGER, ton_amount REAL, status TEXT DEFAULT 'pending', claimed_at TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE bets (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, match_id TEXT NOT NULL, week_id TEXT NOT NULL, prediction TEXT NOT NULL, score_home INTEGER NOT NULL, score_away INTEGER NOT NULL, points_earned INTEGER, created_at TEXT, updated_at TEXT, UNIQUE(user_id, match_id));
CREATE TABLE champions (id INTEGER PRIMARY KEY AUTOINCREMENT, week_id TEXT NOT NULL, user_id TEXT NOT NULL, username TEXT, total_points INTEGER DEFAULT 0, correct_outcomes INTEGER DEFAULT 0, correct_scores INTEGER DEFAULT 0, matches_predicted INTEGER DEFAULT 0, last_bet_at TEXT, rank INTEGER, ton_earned REAL DEFAULT 0.0, computed_at TEXT, UNIQUE(week_id, user_id));
CREATE TABLE leaderboard (user_id TEXT PRIMARY KEY, username TEXT, total_points INTEGER DEFAULT 0, correct_outcomes INTEGER DEFAULT 0, correct_scores INTEGER DEFAULT 0, weeks_played INTEGER DEFAULT 0, weeks_won INTEGER DEFAULT 0, ton_earned REAL DEFAULT 0.0, ton_distributed REAL DEFAULT 0.0, updated_at TEXT);
CREATE TABLE premium_purchases (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL,
  tg_id TEXT NOT NULL,
  stars_amount INTEGER NOT NULL,
  telegram_payment_charge_id TEXT NOT NULL UNIQUE,
  invoice_payload TEXT,
  purchased_at TEXT DEFAULT (datetime('now'))
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_users_tg_id ON users(tg_id);
CREATE INDEX idx_predictions_user_id ON predictions(user_id);
CREATE INDEX idx_predictions_match_id ON predictions(match_id);
CREATE INDEX idx_rewards_user_id ON rewards(user_id);
CREATE INDEX idx_premium_purchases_user_id ON premium_purchases(user_id);
CREATE INDEX idx_premium_purchases_tg_id ON premium_purchases(tg_id);
